32	    template <const char opening_bracket, const char closing_bracket>
33	    static std::pair<bool, size_t>
34	    fileSegmentationEngineJSONEachRowImpl(ReadBuffer & in, DB::Memory<> & memory, size_t min_chunk_size, size_t min_rows)
35	    {
36	        skipWhitespaceIfAny(in);
37	
38	        char * pos = in.position();
39	        size_t balance = 0;
40	        bool quotes = false;
41	        size_t number_of_rows = 0;
42	
43	        while (loadAtPosition(in, memory, pos)
44	               && (balance || memory.size() + static_cast<size_t>(pos - in.position()) < min_chunk_size || number_of_rows < min_rows))
45	        {
46	            const auto current_object_size = memory.size() + static_cast<size_t>(pos - in.position());
47	            if (min_chunk_size != 0 && current_object_size > 10 * min_chunk_size)
48	                throw ParsingException(
49	                    "Size of JSON object is extremely large. Expected not greater than " + std::to_string(min_chunk_size)
50	                        + " bytes, but current is " + std::to_string(current_object_size)
51	                        + " bytes per row. Increase the value setting 'min_chunk_bytes_for_parallel_parsing' or check your data manually, most likely JSON is malformed",
52	                    ErrorCodes::INCORRECT_DATA);
53	
54	            if (quotes)
55	            {
56	                pos = find_first_symbols<'\\', '"'>(pos, in.buffer().end());
57	
58	                if (pos > in.buffer().end())
59	                    throw Exception("Position in buffer is out of bounds. There must be a bug.", ErrorCodes::LOGICAL_ERROR);
60	                else if (pos == in.buffer().end())
61	                    continue;
62	
63	                if (*pos == '\\')
64	                {
65	                    ++pos;
66	                    if (loadAtPosition(in, memory, pos))
67	                        ++pos;
68	                }
69	                else if (*pos == '"')
70	                {
71	                    ++pos;
72	                    quotes = false;
73	                }
74	            }
75	            else
76	            {
77	                pos = find_first_symbols<opening_bracket, closing_bracket, '\\', '"'>(pos, in.buffer().end());
78	
79	                if (pos > in.buffer().end())
80	                    throw Exception("Position in buffer is out of bounds. There must be a bug.", ErrorCodes::LOGICAL_ERROR);
81	                else if (pos == in.buffer().end())
82	                    continue;
83	
84	                else if (*pos == opening_bracket)
85	                {
86	                    ++balance;
87	                    ++pos;
88	                }
89	                else if (*pos == closing_bracket)
90	                {
91	                    --balance;
92	                    ++pos;
93	                }
94	                else if (*pos == '\\')
95	                {
96	                    ++pos;
97	                    if (loadAtPosition(in, memory, pos))
98	                        ++pos;
99	                }
100	                else if (*pos == '"')
101	                {
102	                    quotes = true;
103	                    ++pos;
104	                }
105	
106	                if (balance == 0)
107	                    ++number_of_rows;
108	            }
109	        }
110	
111	        saveUpToPosition(in, memory, pos);
112	        return {loadAtPosition(in, memory, pos), number_of_rows};
113	    }
