228	    template <class Extractor, const char opening_bracket, const char closing_bracket>
229	    static DataTypes determineColumnDataTypesFromJSONEachRowDataImpl(ReadBuffer & in, bool /*json_strings*/, Extractor & extractor)
230	    {
231	        String line = readJSONEachRowLineIntoStringImpl<opening_bracket, closing_bracket>(in);
232	        auto [parser, element] = getJSONParserAndElement();
233	        bool parsed = parser.parse(line, element);
234	        if (!parsed)
235	            throw Exception(ErrorCodes::INCORRECT_DATA, "Cannot parse JSON object here: {}", line);
236	
237	        auto fields = extractor.extract(element);
238	
239	        DataTypes data_types;
240	        data_types.reserve(fields.size());
241	        for (const auto & field : fields)
242	            data_types.push_back(getDataTypeFromFieldImpl(field));
243	
244	        /// TODO: For JSONStringsEachRow/JSONCompactStringsEach all types will be strings.
245	        ///       Should we try to parse data inside strings somehow in this case?
246	
247	        return data_types;
248	    }
