261	    struct JSONEachRowFieldsExtractor
262	    {
263	        template <class Element>
264	        std::vector<Element> extract(const Element & element)
265	        {
266	            /// {..., "<column_name>" : <value>, ...}
267	
268	            if (!element.isObject())
269	                throw Exception(ErrorCodes::INCORRECT_DATA, "Root JSON value is not an object");
270	
271	            auto object = element.getObject();
272	            std::vector<Element> fields;
273	            fields.reserve(object.size());
274	            column_names.reserve(object.size());
275	            for (const auto & key_value_pair : object)
276	            {
277	                column_names.emplace_back(key_value_pair.first);
278	                fields.push_back(key_value_pair.second);
279	            }
280	
281	            return fields;
282	        }
283	
284	        std::vector<String> column_names;
285	    };
