330	    bool readField(
331	        ReadBuffer & in,
332	        IColumn & column,
333	        const DataTypePtr & type,
334	        const SerializationPtr & serialization,
335	        const String & column_name,
336	        const FormatSettings & format_settings,
337	        bool yield_strings)
338	    {
339	        try
340	        {
341	            bool as_nullable = format_settings.null_as_default && !type->isNullable() && !type->isLowCardinalityNullable();
342	
343	            if (yield_strings)
344	            {
345	                String str;
346	                readJSONString(str, in);
347	
348	                ReadBufferFromString buf(str);
349	
350	                if (as_nullable)
351	                    return SerializationNullable::deserializeWholeTextImpl(column, buf, format_settings, serialization);
352	
353	                serialization->deserializeWholeText(column, buf, format_settings);
354	                return true;
355	            }
356	
357	            if (as_nullable)
358	                return SerializationNullable::deserializeTextJSONImpl(column, in, format_settings, serialization);
359	
360	            serialization->deserializeTextJSON(column, in, format_settings);
361	            return true;
362	        }
363	        catch (Exception & e)
364	        {
365	            e.addMessage("(while reading the value of key " + column_name + ")");
366	            throw;
367	        }
368	    }
