370	    DataTypePtr getCommonTypeForJSONFormats(const DataTypePtr & first, const DataTypePtr & second, bool allow_bools_as_numbers)
371	    {
372	        if (allow_bools_as_numbers)
373	        {
374	            auto not_nullable_first = removeNullable(first);
375	            auto not_nullable_second = removeNullable(second);
376	            /// Check if we have Bool and Number and if so make the result type Number
377	            bool bool_type_presents = isBool(not_nullable_first) || isBool(not_nullable_second);
378	            bool number_type_presents = isNumber(not_nullable_first) || isNumber(not_nullable_second);
379	            if (bool_type_presents && number_type_presents)
380	            {
381	                if (isBool(not_nullable_first))
382	                    return second;
383	                return first;
384	            }
385	        }
386	
387	        /// If we have Map and Object, make result type Object
388	        bool object_type_presents = isObject(first) || isObject(second);
389	        bool map_type_presents = isMap(first) || isMap(second);
390	        if (object_type_presents && map_type_presents)
391	        {
392	            if (isObject(first))
393	                return first;
394	            return second;
395	        }
396	
397	        /// If we have different Maps, make result type Object
398	        if (isMap(first) && isMap(second) && !first->equals(*second))
399	            return std::make_shared<DataTypeObject>("json", true);
400	
401	        return nullptr;
402	    }
